{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "ACTION_LOG.A01",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A entrega do redutor em D20 continua correta, mas a mudança aumentou sua folga de 0 para 2 dias; cabe decidir se a confirmação mantém a mesma prioridade."
    },
    {
      "trecho_id": "ACTION_LOG.A02",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A03",
      "rotulo": "CORRETO",
      "informacoes": [],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a partir de D25, data em que o protótipo fica disponível",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D27; a reserva deve começar em D27."
        },
        {
          "citacao": "validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação termina em D37."
        },
        {
          "citacao": "no pedido enviado ao laboratório, consta que o protótipo estará disponível em D26",
          "motivo": "afirmacao_conflitante",
          "correto_seria": "O protótipo estará disponível em D27."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A05",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O prazo do projeto agora termina em D42, gerando dois dias além de D40 e R$ 600 adicionais de gestão e instalação; os termos registrados continuam válidos, mas a ação está ligada a esse custo alterado."
    },
    {
      "trecho_id": "ACTION_LOG.A06",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O motor, antes previsto para D18, agora chega em D22 e fica fora da janela de frete indicada; é preciso decidir se a negociação do frete deve ser ajustada."
    },
    {
      "trecho_id": "RISK_REGISTER.R01",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "essa entrega não tem folga",
          "motivo": "valor_divergente",
          "correto_seria": "A entrega do redutor em D20 tem 2 dias de folga, pois a montagem começa em D22."
        },
        {
          "citacao": "qualquer atraso empurraria a montagem para depois de D20 e a liberação para depois de D40",
          "motivo": "premissa_alterada",
          "correto_seria": "Atraso de até 2 dias do redutor não desloca a montagem nem a liberação; um atraso maior que 2 dias desloca a montagem para depois de D22 e a liberação para depois de D42."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R02",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Uma entrega depois de D20 deslocaria a montagem e, com ela, levaria a validação para depois de D35.",
          "motivo": "premissa_alterada",
          "correto_seria": "A placa e o chicote têm 3 dias de folga: só uma entrega depois de D22 deslocaria a montagem e levaria a validação para depois de D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R03",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "a validação passaria de D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação prevista termina em D37; se o teste exceder 10 dias, ela passará de D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "como compras e fabricação não têm folga, cada dia de reanálise adiaria a liberação",
          "motivo": "premissa_alterada",
          "correto_seria": "Compras e fabricação têm 2 dias de folga em relação à entrega do motor em D22; até 2 dias de reanálise não adiariam a liberação. Mais de 2 dias adiariam a liberação para depois de D42."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R05",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "ele terminaria em D31",
          "motivo": "valor_divergente",
          "correto_seria": "O ensaio repetido integralmente terminaria em D33; ainda antes da validação em D37."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R06",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Se a peça só ficar disponível depois de D20, a montagem começaria depois da data planejada e o fim do projeto seria adiado na mesma medida.",
          "motivo": "premissa_alterada",
          "correto_seria": "O acoplamento pode ficar disponível até D22 sem deslocar a montagem; só se ficar disponível depois de D22 a montagem e o fim do projeto serão adiados."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "DECISION_LOG.D01",
      "rotulo": "PRESERVAR",
